('{ lv: 2, label: "2つの数字のペア", desc: "隠れペア（2つの数字が同じ2マスにしか入らない）と、ネイキッドペア（候補が同じ2つだけのマスが2つある）を、組ごとに色分けします", run: () => showPairs(2) },', '{ lv: 2, label: "Pairs", desc: "Color-codes hidden pairs (two digits that can only go in the same two cells) and naked pairs (two cells with the same two candidates only)", run: () => showPairs(2) },'),
('{ lv: 3, label: "3つの数字の組", desc: "隠れた3つの組と、ネイキッド3つの組（3マスの候補を合わせると3つの数字だけ）を、消せる候補と一緒に示します", run: () => showSubsets(3) },', '{ lv: 3, label: "Triples", desc: "Shows hidden triples and naked triples (three cells whose candidates together are only three digits), with the candidates you can remove", run: () => showSubsets(3) },'),
('{ lv: 3, label: "Xウイング", desc: "2つの行（列）で長方形の角にしか入らない数字と、それで消せる候補を示します", run: () => showXWing() },', '{ lv: 3, label: "X-Wing", desc: "Shows a digit that can only go in the corners of a rectangle across two rows (columns), and the candidates this removes", run: () => showXWing() },'),
('{ lv: 4, label: "4つの数字の組", desc: "3つの組と同じ考え方を、4つの数字と4マスで使います", run: () => showSubsets(4) },', '{ lv: 4, label: "Quads", desc: "The same idea as triples, using four digits and four cells", run: () => showSubsets(4) },'),
('{ lv: 4, label: "ソードフィッシュ", desc: "Xウイングを3つの行（列）に広げたものです", run: () => showSwordfish() },', '{ lv: 4, label: "Swordfish", desc: "An X-Wing extended to three rows (columns)", run: () => showSwordfish() },'),
('{ lv: 4, label: "XYウイング", desc: "候補が2つのマス3つ（AB・AC・BC）を使い、両端から見えるマスのCを消します。Y-Wingとも呼びます", run: () => showWing(false) },', '{ lv: 4, label: "XY-Wing", desc: "Uses three two-candidate cells (AB, AC, BC) to remove C from cells that see both ends. Also called Y-Wing", run: () => showWing(false) },'),
('{ lv: 4, label: "XYZウイング", desc: "軸のマスの候補が3つ（ABC）のXYウイングです。3マスすべてから見えるマスのCを消します", run: () => showWing(true) },', '{ lv: 4, label: "XYZ-Wing", desc: "An XY-Wing whose pivot cell has three candidates (ABC). Removes C from cells that see all three cells", run: () => showWing(true) },'),
('{ lv: 4, label: "スカイスクレイパー", desc: "2か所にしか入らない行（列）を2本使い、端どうしの両方から見えるマスの候補を消します", run: () => showSkyscraper() },', '{ lv: 4, label: "Skyscraper", desc: "Uses two rows (columns) where a digit fits in only two places, and removes the candidate from cells that see both free ends", run: () => showSkyscraper() },'),
('{ lv: 4, label: "唯一解の原則", desc: "ユニークレクタングル。2つのブロックにまたがる長方形の4マスが同じ2つの候補だけになると答えが2通りになってしまうので、そうならないように候補を消します", run: () => showUR() },', '{ lv: 4, label: "Unique Rectangle", desc: "If four cells forming a rectangle across two boxes had only the same two candidates, the puzzle would have two solutions, so candidates are removed to prevent that", run: () => showUR() },'),
('{ lv: 5, label: "シンプルカラーリング", desc: "ある数字が2か所にしか入らない所をたどって2色で塗り、どちらかの色が正解になることを使って候補を消します", run: () => showColoring() },', '{ lv: 5, label: "Simple Coloring", desc: "Follows places where a digit fits in only two spots, coloring them in two colors, and uses the fact that one color must be correct to remove candidates", run: () => showColoring() },'),
('{ lv: 5, label: "リモートペア", desc: "候補が同じ2つのマスが4つ以上つながるとき、交互に入る数字を使って候補を消します", run: () => showRemotePair() },', '{ lv: 5, label: "Remote Pair", desc: "When four or more cells with the same two candidates are linked, uses the alternating digits to remove candidates", run: () => showRemotePair() },'),
('{ lv: 5, label: "XYチェーン", desc: "候補が2つのマスを鎖のようにつなぎ、鎖の両端から見えるマスの候補を消します。順番を番号で示します", run: () => showXYChain() },', '{ lv: 5, label: "XY-Chain", desc: "Links two-candidate cells into a chain and removes candidates from cells that see both ends. The order is shown with numbers", run: () => showXYChain() },'),
('{ lv: 5, label: "チェーン", desc: "「2か所にしか入らない数字」と「候補が2つのマス」を交互につなぎ、両端のどちらかが正しいことを使って候補を消します", run: () => showChain() },', '{ lv: 5, label: "Chain", desc: "Alternately links “a digit that fits in only two places” and “a cell with two candidates,” and uses the fact that one end must be true to remove candidates", run: () => showChain() },'),
('{ lv: 6, label: "背理法", desc: "候補が2つのマスに片方を仮に入れ、矛盾が出たらもう一方が答えだと分かります", run: () => showContradiction() },', '{ lv: 6, label: "Contradiction", desc: "Tentatively places one of the two candidates in a cell; if that leads to a contradiction, the other one is the answer", run: () => showContradiction() },'),
('{ label: "答えと理由", desc: "入る数字と、その理由を教えます。すぐ決まるマスがなければ、上級の解き方で候補を消してから答えを示します（背理法が必要なら答えだけ示します）", run: () => runHint(true) },', '{ label: "Answer and reason", desc: "Tells you a digit and why it goes there. If no cell can be decided right away, it removes candidates with advanced techniques first (if contradiction is needed, it only shows the answer)", run: () => runHint(true) },'),
('.textContent = `もう少しがんばりましょう。（レベル${lim}までのヒントは控える設定です）`;', '.textContent = `Keep trying a little longer. (Your settings hold back hints up to level ${lim}.)`;'),
('st.setAttribute("aria-label", `レベル${k.lv}`);', 'st.setAttribute("aria-label", `Level ${k.lv}`);'),
('q.textContent = "？";', 'q.textContent = "?";'),
('q.setAttribute("aria-label", `${k.label}の説明`);', 'q.setAttribute("aria-label", `About ${k.label}`);'),
('k.label === "注目するマス"', 'k.label === "Cell to focus on"'),
('.hm-go[data-kind=\\"注目するマス\\"] .hm-label', '.hm-go[data-kind=\\"Cell to focus on\\"] .hm-label'),
('? "次に注目するマス" : "注目するマス";', '? "Next cell to focus on" : "Cell to focus on";'),
('{ key: "blank", label: "未確定のマスを空白にする", desc: "大きな数字が入っていないマスの小さな数字を、すべて隠します" },', '{ key: "blank", label: "Hide candidates in open cells", desc: "Hides all small digits in cells without a large digit" },'),
('{ key: "", label: "未確定のマスの候補を表示する", desc: "小さな数字を表示する、いつもの表示です" },', '{ key: "", label: "Show candidates in open cells", desc: "The normal view, showing small digits" },'),
('{ key: "answer", label: "正解を表示する", desc: "確定していないマスに正解を緑で表示します。違う確定候補は赤い背景になります。ほかの表示を選ぶと元に戻ります" },', '{ key: "answer", label: "Show solution", desc: "Shows the solution in green in unconfirmed cells. Wrong confirmed digits get a red background. Choose another view to go back" },'),
('workMsg.textContent = "この問題は答えがないため、正解を表示できません。"; return; }', 'workMsg.textContent = "This puzzle has no solution, so it can’t be shown."; return; }'),
('workMsg.textContent = "正解を緑で表示しています。" + (solution && solution.n > 1 ? "（答えが1つに決まらない問題なので、答えの1つです）" : "") + "元に戻すときは「表示方法変更」でほかの表示を選んでください。";', 'workMsg.textContent = "Showing the solution in green. " + (solution && solution.n > 1 ? "(This puzzle has more than one solution, so this is one of them.) " : "") + "To go back, choose another option under “View.”";'),
